suppressPackageStartupMessages({library(SummarizedExperiment);library(PharmacoGx)})
source('workflow/scripts/molecular_annotations.R')
x<-SummarizedExperiment(assays=list(value=matrix(1:4,2)),metadata=list(value_type='source units'))
a<-list(rnaseq.fpkm=x,microarray.rma=x,mutation.wes=x,proteomics.swath=x,dtp.protein=x)
b<-annotate_molecular_types(a)
stopifnot(identical(a$rnaseq.fpkm,b$rnaseq.fpkm)==FALSE)
for(n in names(a))stopifnot(identical(assays(a[[n]]),assays(b[[n]])),identical(metadata(a[[n]])$value_type,metadata(b[[n]])$value_type))
stopifnot(PharmacoGx:::.isContinuousMolecularAnnotation(metadata(b$rnaseq.fpkm)$annotation),PharmacoGx:::.isContinuousMolecularAnnotation(metadata(b$microarray.rma)$annotation),PharmacoGx:::.isBinaryMolecularAnnotation(metadata(b$mutation.wes)$annotation),!PharmacoGx:::.isContinuousMolecularAnnotation(metadata(b$proteomics.swath)$annotation))
cat('PASS: molecular annotations preserve all values and units, identify RNA/mutation types, and do not mislabel unsupported protein/heterogeneous assays.\n')
